#include <biglybtc/tag_constraints.hpp>
#include <biglybtc/bencode.hpp>
#include <fstream>
#include <iostream>
#include <stdexcept>
namespace b=biglybtc::core;namespace c=b::tags::constraints;namespace t=b::tags::runtime;
namespace {
void need(bool value,const char* message){if(!value){throw std::runtime_error(message);}}
std::vector<t::Type> source(bool alias=false){std::vector<t::Type> types;for(int id=1;id<=5;++id){types.push_back({id,{},true});}if(alias){types[2].tags.push_back({2,2,u"Generated-1",{},true,t::Membership::Present});}types[3].tags.push_back({1,4,u"Generated-1",{},true,t::Membership::Absent});types.push_back({7,{{1,0,{}, {},false,t::Membership::Absent}},false});return types;}
c::Result<c::Value> evaluate(const c::Facts& facts,std::u16string_view expression=u"hasTag(\"Generated-1\")"){auto compiled=c::compile(expression);need(bool(compiled),"Generated negative condition compile");return c::evaluate(*compiled,facts);}
void actualOriginalHasTagValues(){std::ifstream file(PEER_SET_CACHE_FIXTURE,std::ios::binary);auto original=b::Document::parse(std::string{std::istreambuf_iterator<char>(file),{}});need(bool(original),"Actual peer cache fixture");unsigned cases=0,negative=0;for(const auto& row:original->find("rows")->children){if(row.find("function")->bytes!="hasTag"){continue;}c::Facts facts;facts.tagRegistry=*t::Registry::create(source(row.find("manual_alias")->integer!=0),false);facts.downloadTagCensus=true;facts.peerSetObservationComplete=true;if(row.find("peer_cache")->integer){facts.peerSetTagNames.push_back(u"Generated-1");}auto value=evaluate(facts);const bool expected=row.find("value")->integer!=0;need(value&&c::truth(*value).value()==expected,"Actual original partial-domain hasTag differs");if(!expected){++negative;facts.peerSetObservationComplete=false;value=evaluate(facts);need(!value&&value.error().kind==c::ProblemKind::Unavailable,"Unobserved peer cache inferred empty");facts.peerSetObservationComplete=true;facts.downloadTagCensus=false;need(!evaluate(facts),"Partial metadata alone authorised a negative");}++cases;}need(cases==12&&negative==3,"Actual original hasTag cases lost");}
void missingAmbiguousAndImpossibleSources(){auto types=source();auto registry=t::Registry::create(types,false);need(registry&&registry->hasName(u"Generated-1",2)==t::Truth::Unknown&&registry->downloadConstraintName(u"Generated-1",true)==t::Truth::No,"Scoped direct negative made global census complete");need(registry->downloadConstraintName(u"Generated-1",false)==t::Truth::Unknown,"Missing peer observation inferred empty");
 for(unsigned at=0;at<5;++at){auto missing=types;missing[at].complete=false;auto current=t::Registry::create(missing,false);need(current&&current->downloadConstraintName(u"Generated-1",true)==t::Truth::Unknown,"Partial family produced a negative");missing.erase(missing.begin()+at);current=t::Registry::create(missing,false);need(current&&current->downloadConstraintName(u"Generated-1",true)==t::Truth::Unknown,"Missing family produced a negative");}
 types=source();types[1].tags.push_back({0,2,u"Other known name",{},true,t::Membership::Unknown});registry=t::Registry::create(types,false);need(registry&&registry->downloadConstraintName(u"Generated-1",true)==t::Truth::No,"Unrelated observed name hid a negative");types[1].tags[0].name=u"Generated-1";registry=t::Registry::create(types,false);need(registry&&registry->downloadConstraintName(u"Generated-1",true)==t::Truth::Unknown,"Unknown same-name state membership inferred absent");types[1].tags[0].membership=t::Membership::Present;registry=t::Registry::create(types,false);need(registry&&registry->downloadConstraintName(u"Generated-1",false)==t::Truth::Yes,"Known positive was hidden by peer uncertainty");
 types=source();types[4].tags.push_back({1,2,{}, {},true,t::Membership::Unknown});registry=t::Registry::create(types,false);need(registry&&registry->downloadConstraintName(u"Generated-1",true)==t::Truth::Unknown,"Unknown possible member name inferred absent");types[4].tags[0].membership=t::Membership::Absent;registry=t::Registry::create(types,false);need(registry&&registry->downloadConstraintName(u"Generated-1",true)==t::Truth::No,"Known nonmember with unknown name became a member");
 types=source();types.push_back({8,{},true});registry=t::Registry::create(types,false);need(registry&&registry->downloadConstraintName(u"Generated-1",true)==t::Truth::Unknown,"Future family was ignored");types=source();types.push_back({6,{{1,2,u"Generated-1",{},true,t::Membership::Unknown}},true});registry=t::Registry::create(types,false);need(registry&&registry->downloadConstraintName(u"Generated-1",true)==t::Truth::Unknown,"Unsupported populated suggestion source inferred empty");types=source();types.back().tags[0].taggableTypes.reset();registry=t::Registry::create(types,false);need(registry&&registry->downloadConstraintName(u"Generated-1",true)==t::Truth::Unknown,"Unknown Swarm capability became TT_NONE");
 c::Facts facts;facts.tagRegistry=*t::Registry::create(source(),false);facts.downloadTagCensus=facts.peerSetObservationComplete=true;need(!evaluate(facts,u"!hasTag(\"Unregistered\")"),"Unregistered constructor symbol accepted");auto partialGroups=source();partialGroups[4].tags.push_back({1,2,u"Generated internal",{},false,t::Membership::Unknown});facts.tagRegistry=*t::Registry::create(std::move(partialGroups),false);need(!evaluate(facts,u"!hasTagGroup(\"Generated group\")"),"Name proof inferred an unknown member group");need(t::Registry{}.downloadConstraintName(u"Generated-1",true)==t::Truth::Unknown,"Missing registry inferred empty");need(facts.tagRegistry->downloadConstraintName(std::u16string(4097,u'x'),true)==t::Truth::Unknown,"Name bounds ignored");}
}
int main(){try{actualOriginalHasTagValues();missingAmbiguousAndImpossibleSources();}catch(const std::exception& error){std::cerr<<error.what()<<'\n';return 1;}std::cout<<"PASS12 actual original hasTag values;scoped negative source and peer receipt bounds\n";}
